WITH flattened_attrs AS (SELECT id, service, host, latency_ms, status_code, payload_json, context['trace'] AS trace, COALESCE(context['region'], 'none') AS region_or_default FROM app_logs WHERE host = 'h3') SELECT *, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host), 4) latency_ms_share, LAG(latency_ms, 2) OVER (PARTITION BY service ORDER BY status_code, id) prev_latency_ms FROM flattened_attrs;
